<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Application\Policy\Filter;

use Throwable;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Access\UserGroupMembership\Application\Service\Visibility\UserGroupMembershipRestrictFilterToVisibility;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TenantAccesible
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(UserGroupMembershipRestrictFilterToVisibility $event): UserGroupMembershipRestrictFilterToVisibility
    {
        $this->logDebug("Check TenantAccesible User group membership");
        $span = $this->startSpan("Check TenantAccesible User group membership");
        try {
            $userContext = $this->context->getIdentity();
            if (!$userContext->hasAnyRole('platform:*')) {
                $userTenantTenantAccesible = $userContext->tenant;
                if (!$userContext->anonymous && null !== $userTenantTenantAccesible) {
                    $event->userGroupMembershipFilter = $event->userGroupMembershipFilter->withUserTenantTenantAccesible($userTenantTenantAccesible);
                } else {
                    throw new UnauthorizedException('The claim tenant is required');
                }
            }
            return $event;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
